def test_the_receipt_describes_the_attempt() -> None:
    receipts = InMemoryReceiptStore()
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.DECLINED), receipts)

    handler.handle("ORD-3", Money(Decimal("10.50"), "eur"))

    assert receipts.saved == {"ORD-3": "EUR 10.50 -> DECLINED"}
